namespace MouseClicker;

internal static partial class HelpContent
{
    private static HelpPage EuropeanPage(HelpTopic topic, string title, string summary, params HelpSection[] sections) =>
        new(topic, title, summary, Array.AsReadOnly(sections));

    private static partial void AddOtherLanguages(Dictionary<string, HelpCatalog> catalogs)
    {
        catalogs["fr-FR"] = new("Guide d’utilisation", "Rubriques", "Rechercher dans le guide…", "Aucune rubrique trouvée. Essayez un autre mot.", "Fermer", "Guide du clic conditionnel", Array.AsReadOnly(new[]
        {
            EuropeanPage(HelpTopic.QuickStart, "Premiers pas", "Gardez ce guide ouvert à côté du programme pour suivre les étapes.",
                new("Votre premier clic", "1. Cliquez sur Ajouter, tracez la zone où cliquer et donnez-lui un nom.\n2. Réglez l’intervalle en millisecondes et choisissez la séquence.\n3. Cliquez sur Démarrer les clics. Utilisez Arrêter ou ESC pour terminer."),
                new("Cliquer lorsqu’une image apparaît", "Ajoutez une zone, sélectionnez-la et cliquez sur Modifier la condition. Le menu contextuel et le double-clic restent disponibles. La rubrique de configuration visuelle explique comment définir séparément la détection et la destination du clic. Le guide ne bloque pas la fenêtre principale.")),
            EuropeanPage(HelpTopic.AreasAndButtons, "Zones et boutons de souris", "Choisissez où cliquer et avec quel bouton.",
                new("Gérer les zones", "Cliquez sur Ajouter et tracez un rectangle sur le bureau. Nommez chaque zone. Sélectionnez une entrée pour la supprimer ou la déplacer vers le haut ou le bas. Cliquez à nouveau sur l’entrée sélectionnée pour la désélectionner. Le clic se fait à une position aléatoire dans le rectangle."),
                new("Boutons et repères", "Le menu contextuel permet de choisir le bouton gauche [L] ou droit [R]. Si les contours sont affichés, le bleu repère la zone survolée ou sélectionnée et le vert la zone actuellement cliquée. Sous Windows 10 2004 ou ultérieur, les contours restent visibles mais sont exclus des captures de reconnaissance. Si cette exclusion est indisponible ou échoue, ils sont masqués. Les zones peuvent se trouver sur différents écrans.")),
            EuropeanPage(HelpTopic.TimingAndOrder, "Intervalle et ordre", "Le rythme des clics et celui de la détection sont indépendants.",
                new("Intervalle et variation", "L’intervalle global est exprimé en ms. La variation ajoute ou retire une durée aléatoire. Si la somme est négative, sa valeur absolue est utilisée, avec un minimum de 10 ms. Une forte variation peut donc augmenter l’attente moyenne."),
                new("Séquences", "Boucle dans l’ordre parcourt la liste puis recommence. Boucle aléatoire choisit une entrée avant de l’exécuter. Un passage dans l’ordre parcourt la liste une seule fois. Une entrée conditionnelle attend que son image corresponde avant de cliquer et de passer à la suivante ; elle n’est pas ignorée. En mode Boucle aléatoire, le programme attend l’entrée déjà choisie.")),
            EuropeanPage(HelpTopic.ImageConditionSetup, "Configurer un clic conditionnel", "Exemple : détecter une icône Terminé en haut à gauche et cliquer sur Suivant en bas à droite.",
                new("Trois éléments distincts", "La zone de clic indique où agir. La zone de détection indique où chercher. Le modèle est la petite image à retrouver. Ces éléments sont indépendants : les deux zones peuvent être éloignées ou sur des écrans différents. Gardez le guide ouvert à côté de l’application. Pendant la capture ou le test, il devient temporairement transparent puis revient. Pendant la session, placez le programme et le guide hors de la zone de détection."),
                new("Les huit étapes", "1. Ajoutez et nommez la zone à cliquer sur Suivant.\n2. Faites un clic droit sur l’entrée puis Modifier la condition, ou double-cliquez.\n3. Activez la condition visuelle.\n4. Sélectionnez la zone de détection autour de l’emplacement prévu de l’icône.\n5. Capturez une petite image distinctive ou importez un PNG, JPG ou BMP. En mode taille d’origine, le modèle doit tenir dans la zone.\n6. Testez la reconnaissance : consultez le score et le cadre vert. Ce test ne clique pas.\n7. Enregistrez la condition et revenez à la fenêtre principale.\n8. Démarrez les clics. Faites apparaître l’icône ; ESC arrête la session. Une image importée peut servir à attendre une cible qui n’est pas encore visible."),
                new("Adaptation automatique de taille", "Choisissez la zone avant capture ou importation. Le cadre se déplace librement, même sur un autre écran ; sa largeur et sa hauteur sont limitées à la zone. Entrée confirme, Échap annule. L’import conserve l’image entière sans recadrage obligatoire. Utilisez le bouton de recadrage séparé si nécessaire et confirmez ; annuler conserve le modèle. Les positions de capture et de détection sont indépendantes.\n\nLes nouvelles conditions activent l’adaptation de taille. Les anciens fichiers conservent la taille d’origine ; vous pouvez activer l’adaptation. La recherche teste plusieurs tailles proportionnelles dans une plage limitée : elle est plus lente et ne garantit pas toutes les échelles. Le test affiche l’échelle et le cadre de correspondance. Les modèles sont limités à 32 Mo (environ 33 mégapixels).\n\nLes contours de détection orange en pointillés ont un interrupteur indépendant des contours de clic. Les deux sont exclus des captures si possible, sinon masqués pendant les sessions conditionnelles.")),
            EuropeanPage(HelpTopic.ImageConditionParameters, "Comprendre les paramètres visuels", "Commencez avec les valeurs proposées, puis vérifiez avec le test.",
                new("Score et fréquence", "Le seuil initial est 0,90 : ce score n’est pas une probabilité. Comparez les résultats sur une vraie cible et sur un fond sans cible avant de l’ajuster. La vérification se fait par défaut toutes les 200 ms, indépendamment de l’intervalle global entre clics. Deux images successives doivent correspondre."),
                new("Déclenchement et attente", "Une fois par apparition clique une seule fois tant que l’image reste présente. Deux vérifications successives sans correspondance réarment la condition. Une cible déjà visible au démarrage peut déclencher le premier clic. Répéter tant que visible reste soumis à la séquence et à l’intervalle global. L’attente maximale initiale est de 60 s ; 0 signifie illimitée. Le dépassement arrête toute la session. Le délai obligatoire entre clics n’est pas compté dans cette attente.")),
            EuropeanPage(HelpTopic.ImageConditionTroubleshooting, "Résoudre les problèmes de reconnaissance", "Testez sans clic avant de relancer la session.",
                new("Aucune correspondance ou image refusée", "Seul le bureau visible est lu : déplacez le programme et le guide hors de la zone de détection et restaurez les fenêtres réduites. Utilisez des détails distinctifs stables, pas une couleur unie. À la taille d’origine, le modèle doit tenir dans la zone ; activez l’adaptation, recadrez si souhaité ou agrandissez la zone. Le mode automatique ne garantit pas toutes les échelles ; rotation ou changement de thème peuvent demander une nouvelle capture. Augmentez le seuil en cas de faux positif."),
                new("Faux positifs, attente ou lenteur", "Augmentez le seuil ou choisissez un modèle plus distinctif en cas de faux positif. Si l’image reste visible mais qu’un seul clic se produit, vérifiez le mode Une fois par apparition ; choisissez Répéter pour des clics répétés. La séquence peut encore attendre une entrée précédente. Un dépassement du délai arrête la session. Réduisez la zone de détection pour alléger le traitement ; une apparition plus courte que l’intervalle de détection peut être manquée.")),
            EuropeanPage(HelpTopic.HotkeysAndConfiguration, "Raccourcis et configurations", "Conservez vos réglages et gardez une commande d’arrêt accessible.",
                new("Démarrer et arrêter", "F6 est le raccourci initial ; ESC arrête les clics en cours. Paramètres → Paramètres des raccourcis accepte F6–F12, Insert, Home, End, PageUp, PageDown et Pause sans Ctrl, Alt, Shift ni Win. Ces préférences sont propres à l’utilisateur Windows, séparées du fichier JSON."),
                new("Enregistrer et charger", "Arrêtez la session avant de modifier ou charger une configuration. Fichier permet d’enregistrer les zones, boutons, délais, séquence et conditions dans un JSON. Les modèles y sont intégrés : aucun chemin externe à maintenir. Les anciens fichiers sans condition restent des clics ordinaires. Le mode SendInput génère des événements logiciels, pas un véritable périphérique matériel."),
                new("Enregistrement et restauration automatiques", "À la fermeture de la fenêtre principale, l’application enregistre la configuration actuelle pour l’utilisateur Windows et la restaure au prochain démarrage. Fichier : %LOCALAPPDATA%\\MouseClicker\\last-session.json. Pour repartir de zéro, fermez l’application et supprimez ce fichier. La commande Fichier → Enregistrer la configuration sert toujours à exporter un fichier JSON."))
        }));

        catalogs["de-DE"] = new("Bedienungsanleitung", "Themen", "Anleitung durchsuchen…", "Keine Themen gefunden. Versuchen Sie einen anderen Suchbegriff.", "Schließen", "Anleitung für Bildbedingungen", Array.AsReadOnly(new[]
        {
            EuropeanPage(HelpTopic.QuickStart, "Erste Schritte", "Lassen Sie diese Anleitung neben dem Programm geöffnet und arbeiten Sie die Schritte ab.",
                new("Der erste Klick", "1. Klicken Sie auf Hinzufügen, ziehen Sie den Klickbereich auf und benennen Sie ihn.\n2. Stellen Sie das Intervall in Millisekunden und die Reihenfolge ein.\n3. Starten Sie die Klicks. Mit Stopp oder ESC beenden Sie den Vorgang."),
                new("Auf ein Bild warten", "Legen Sie einen Klickbereich an, wählen Sie ihn aus und klicken Sie auf Bedingung bearbeiten. Rechtsklick und Doppelklick sind ebenfalls möglich. Die Bildanleitung erklärt die getrennte Wahl von Suchbereich, Vorlage und Klickziel. Das Hilfefenster blockiert das Hauptfenster nicht.")),
            EuropeanPage(HelpTopic.AreasAndButtons, "Bereiche und Maustasten", "Bestimmen Sie das Klickziel und die zu verwendende Taste.",
                new("Bereiche verwalten", "Klicken Sie auf Hinzufügen und ziehen Sie ein Rechteck auf dem Desktop. Benennen Sie die Bereiche; entfernen oder verschieben Sie einen ausgewählten Eintrag mit den entsprechenden Schaltflächen. Ein erneuter Klick auf den ausgewählten Eintrag hebt die Auswahl auf. Die Klickposition wird zufällig innerhalb des Rechtecks gewählt."),
                new("Tasten und Markierungen", "Im Kontextmenü wählen Sie die linke [L] oder rechte [R] Maustaste. Bei eingeschalteten Rahmen markiert Blau den ausgewählten oder mit der Maus berührten Bereich, Grün den gerade angeklickten. Ab Windows 10 2004 bleiben die Rahmen sichtbar und werden aus Erkennungsaufnahmen ausgeschlossen. Ist dies nicht verfügbar oder schlägt es fehl, werden die Rahmen bei Bildbedingungen ausgeblendet. Bereiche dürfen auf verschiedenen Monitoren liegen.")),
            EuropeanPage(HelpTopic.TimingAndOrder, "Zeitabstände und Reihenfolge", "Klickintervall und Prüfintervall sind unterschiedliche Einstellungen.",
                new("Intervall und Streuung", "Das globale Intervall wird in ms angegeben. Die Streuung addiert oder subtrahiert einen zufälligen Zeitwert. Eine negative Summe wird als Absolutwert verwendet; mindestens 10 ms bleiben erhalten. Große Streuung kann die mittlere Wartezeit erhöhen."),
                new("Ablauf", "Der Reihe nach wiederholen geht die Liste durch und beginnt danach wieder von vorn. Zufällig wiederholen wählt zuerst einen Eintrag. Einmal der Reihe nach geht die Liste einmal durch. Bei einer Bildbedingung wartet der aktuelle Eintrag auf eine Übereinstimmung und klickt erst dann; er wird nicht übersprungen. Beim Modus Zufällig wiederholen wird auf den bereits ausgewählten Eintrag gewartet.")),
            EuropeanPage(HelpTopic.ImageConditionSetup, "Bildbedingung Schritt für Schritt", "Beispiel: links oben ein Fertig-Symbol erkennen und rechts unten auf Weiter klicken.",
                new("Drei getrennte Angaben", "Klickbereich bedeutet: Wo wird geklickt? Suchbereich bedeutet: Wo wird gesucht? Die Vorlage bestimmt: Welches Bild wird gesucht? Die Bereiche sind unabhängig und dürfen auf verschiedenen Monitoren liegen. Stellen Sie die Anleitung zum Mitlesen neben das Programm. Bei Aufnahme oder Test wird sie kurz transparent und danach wiederhergestellt. Während der Ausführung dürfen Programm und Anleitung den Suchbereich nicht verdecken."),
                new("Acht Schritte", "1. Legen Sie den Klickbereich über Weiter an und benennen Sie ihn.\n2. Öffnen Sie per Rechtsklick Bedingung bearbeiten oder per Doppelklick die Einstellungen.\n3. Aktivieren Sie die Bildbedingung.\n4. Wählen Sie den Suchbereich um die erwartete Position des Symbols.\n5. Nehmen Sie eine kleine, markante Vorlage auf oder importieren Sie PNG, JPG oder BMP. Bei Originalgröße muss die Vorlage in den Suchbereich passen.\n6. Testen Sie die Erkennung und prüfen Sie Wert und grünen Trefferrahmen. Dabei wird nicht geklickt.\n7. Speichern Sie die Bedingung und kehren Sie zum Hauptfenster zurück.\n8. Starten Sie die Klicks und lassen Sie das Symbol erscheinen. ESC stoppt. Eine importierte Vorlage darf auf ein Bild warten, das momentan noch nicht sichtbar ist."),
                new("Automatische Zielgröße", "Wählen Sie vor Aufnahme oder Import den Suchbereich. Der Aufnahmerahmen ist frei beweglich, auch auf andere Monitore; Breite und Höhe bleiben auf den Suchbereich begrenzt. Enter bestätigt, Esc bricht ab. Der Import behält das gesamte Original ohne erzwungenen Zuschnitt. Bei Bedarf separat zuschneiden und bestätigen; Abbrechen behält die Vorlage. Aufnahme- und Suchposition sind unabhängig.\n\nNeue Bedingungen passen die Zielgröße standardmäßig an. Alte Konfigurationen behalten die Originalgröße; die Anpassung lässt sich einschalten. Die Suche prüft mehrere proportionale Größen in einem begrenzten Bereich, benötigt mehr Zeit und garantiert nicht jeden Maßstab. Der Test zeigt Maßstab und Trefferrahmen. Vorlagen sind auf 32 MB (etwa 33 Megapixel) begrenzt.\n\nOrange gestrichelte Suchrahmen haben einen eigenen Schalter, unabhängig von Klickrahmen. Beide werden nach Möglichkeit von Aufnahmen ausgeschlossen, sonst während bedingter Sitzungen verborgen.")),
            EuropeanPage(HelpTopic.ImageConditionParameters, "Bildparameter verstehen", "Beginnen Sie mit den Vorgaben und passen Sie sie anhand des Erkennungstests an.",
                new("Schwelle und Prüftakt", "Die Standardschwelle beträgt 0,90. Der Wert ist keine Wahrscheinlichkeit. Testen Sie Zielbild und Hintergrund ohne Ziel vor einer Änderung. Das Prüfintervall beträgt zunächst 200 ms und ist vom globalen Klickintervall unabhängig. Zwei aufeinanderfolgende Prüfungen müssen übereinstimmen."),
                new("Auslösung und Zeitlimit", "Einmal pro Erscheinen klickt bei einem dauerhaft sichtbaren Bild nur einmal. Zwei aufeinanderfolgende Prüfungen ohne Treffer geben die Auslösung wieder frei. Ein beim Start bereits sichtbares Ziel kann den ersten Klick auslösen. Wiederholen solange sichtbar beachtet weiterhin Reihenfolge und Klickintervall. Das Zeitlimit ist zunächst 60 s, mit 0 unbegrenzt. Bei Überschreitung stoppt die gesamte Sitzung. Die vorgeschriebene Pause zwischen Klicks zählt nicht als Wartezeit für die Bedingung.")),
            EuropeanPage(HelpTopic.ImageConditionTroubleshooting, "Erkennungsprobleme beheben", "Prüfen Sie die Erkennung ohne Klick, bevor Sie den Ablauf erneut starten.",
                new("Kein Treffer oder ungültige Vorlage", "Nur der sichtbare Desktop wird gelesen. Programm und Anleitung außerhalb des Suchbereichs platzieren und minimierte Fenster wiederherstellen. Markante stabile Details statt einfarbiger Bilder verwenden. Bei Originalgröße muss die Vorlage in den Bereich passen; Anpassung einschalten, optional zuschneiden oder Bereich erweitern. Automatik garantiert nicht jeden Maßstab; Drehungen und Themenwechsel können eine Neuaufnahme erfordern. Bei Fehltreffern Schwelle erhöhen."),
                new("Falsche Treffer, Warten oder hohe Last", "Bei falschen Treffern erhöhen Sie die Schwelle oder verwenden eine markantere Vorlage. Ein dauerhaftes Bild erzeugt im Modus Einmal pro Erscheinen keinen zweiten Klick; wählen Sie bei Bedarf Wiederholen. Möglicherweise wartet der Ablauf noch auf den vorherigen Eintrag. Ein Zeitlimit stoppt die gesamte Sitzung. Ein kleinerer Suchbereich senkt den Aufwand. Kürzere Bildwechsel als das Prüfintervall können unbemerkt bleiben.")),
            EuropeanPage(HelpTopic.HotkeysAndConfiguration, "Tastenkürzel und Konfigurationen", "Speichern Sie Einstellungen und behalten Sie eine schnelle Stoppmöglichkeit.",
                new("Start und Stopp", "Standardmäßig startet und stoppt F6; ESC beendet laufende Klicks. Unter Einstellungen → Tastenkürzel sind F6–F12, Insert, Home, End, PageUp, PageDown und Pause ohne Ctrl, Alt, Shift oder Win möglich. Diese benutzerspezifischen Einstellungen werden getrennt vom JSON gespeichert."),
                new("Speichern und Laden", "Stoppen Sie vor dem Bearbeiten oder Laden einer Konfiguration. Datei speichert Bereiche, Maustasten, Zeiten, Reihenfolge und Bedingungen als JSON. Vorlagen werden eingebettet und benötigen keinen externen Dateipfad. Alte Dateien ohne Bildbedingungen führen weiterhin normale Klicks aus. SendInput erzeugt Software-Eingaben und stellt keine echte Hardware dar."),
                new("Automatisch speichern und wiederherstellen", "Beim Schließen des Hauptfensters speichert die App die aktuelle Konfiguration für den aktuellen Windows-Benutzer und stellt sie beim nächsten Start wieder her. Datei: %LOCALAPPDATA%\\MouseClicker\\last-session.json. Um leer zu beginnen, schließen Sie die App und löschen diese Datei. Datei → Konfiguration speichern exportiert weiterhin eine JSON-Datei."))
        }));

        catalogs["es-ES"] = new("Guía de uso", "Temas", "Buscar en la guía…", "No hay temas coincidentes. Pruebe otra palabra.", "Cerrar", "Guía de clic por imagen", Array.AsReadOnly(new[]
        {
            EuropeanPage(HelpTopic.QuickStart, "Primeros pasos", "Mantenga esta guía al lado del programa mientras realiza los pasos.",
                new("Su primer clic", "1. Pulse Añadir, dibuje la zona de clic y asígnele un nombre.\n2. Ajuste el intervalo en milisegundos y la secuencia.\n3. Inicie los clics. Para terminar, pulse Detener o ESC."),
                new("Esperar una imagen", "Añada y seleccione una zona y pulse Editar condición. También puede usar el botón derecho o el doble clic. La guía de imágenes explica cómo separar el destino, el área de búsqueda y la plantilla. Puede operar la ventana principal sin cerrar la ayuda.")),
            EuropeanPage(HelpTopic.AreasAndButtons, "Zonas y botones del ratón", "Elija dónde actuar y con qué botón.",
                new("Organizar zonas", "Pulse Añadir y dibuje un rectángulo en el escritorio. Nombre cada zona; seleccione una entrada para eliminarla o subirla y bajarla. Volver a pulsar una entrada seleccionada quita la selección. Cada clic elige una posición aleatoria dentro del rectángulo."),
                new("Botones y colores", "El menú contextual permite elegir el botón izquierdo [L] o derecho [R]. Con los marcos activados, el azul indica la zona seleccionada o señalada y el verde la que recibe el clic actual. En Windows 10 2004 o posterior, los marcos permanecen visibles pero se excluyen de las capturas de reconocimiento. Si la exclusión no está disponible o falla, se ocultan durante estas sesiones. Las zonas pueden estar en monitores distintos.")),
            EuropeanPage(HelpTopic.TimingAndOrder, "Intervalos y orden", "El intervalo de clic y el de detección son independientes.",
                new("Intervalo y variación", "El intervalo global se expresa en ms. La variación suma o resta un tiempo aleatorio. Si el total es negativo, se utiliza su valor absoluto, siempre con un mínimo de 10 ms. Una variación grande puede aumentar la espera media."),
                new("Secuencias", "Repetir en orden recorre la lista y vuelve a empezar. Repetir al azar elige primero una entrada. Una vez en orden recorre la lista una sola vez. Una entrada condicional espera su imagen antes de hacer clic y avanzar; no se omite. En Repetir al azar se espera la entrada ya elegida, sin escoger otra mientras no coincida.")),
            EuropeanPage(HelpTopic.ImageConditionSetup, "Configurar la condición visual", "Ejemplo: detectar un icono Listo arriba a la izquierda y pulsar Siguiente abajo a la derecha.",
                new("Tres elementos independientes", "La zona de clic indica dónde pulsar; la zona de detección indica dónde buscar; la plantilla indica qué imagen buscar. Las dos zonas pueden estar separadas e incluso en monitores distintos. Deje la guía abierta al lado del programa. Durante la captura o prueba se vuelve transparente temporalmente y después se restaura. Durante la sesión, coloque el programa y la ayuda fuera de la zona de detección."),
                new("Ocho pasos", "1. Añada y nombre la zona de clic sobre Siguiente.\n2. Abra Editar condición con el botón derecho sobre la entrada o haga doble clic.\n3. Active la condición visual.\n4. Seleccione el área donde debe aparecer el icono.\n5. Capture una plantilla pequeña y distintiva o importe PNG, JPG o BMP. Debe caber dentro de la zona de detección.\n6. Pruebe el reconocimiento y consulte la puntuación y el marco verde. La prueba no hace clic.\n7. Guarde la condición y vuelva a la ventana principal.\n8. Inicie los clics y haga aparecer el icono. ESC detiene la sesión. Puede importar una imagen para esperar un objetivo que todavía no esté visible."),
                new("Adaptación automática del tamaño", "Seleccione el área antes de capturar o importar. Mueva el marco libremente, incluso a otra pantalla; su anchura y altura no superan el área. Enter confirma y Esc cancela. La importación conserva la imagen completa sin recorte obligatorio. Use el botón de recorte aparte si lo desea y confirme; cancelar conserva la plantilla. Las posiciones son independientes.\n\nLas condiciones nuevas activan la adaptación de tamaño. Las configuraciones antiguas conservan el tamaño original; puede activar la adaptación. Se prueban varios tamaños proporcionales en un intervalo limitado: tarda más y no garantiza todas las escalas. La prueba muestra la escala y el marco de coincidencia. Las plantillas tienen un límite de 32 MB (unos 33 megapíxeles).\n\nLos marcos naranjas discontinuos de detección tienen un control independiente de los de clic. Ambos se excluyen de las capturas si es posible; si no, se ocultan en sesiones condicionales.")),
            EuropeanPage(HelpTopic.ImageConditionParameters, "Parámetros de reconocimiento", "Empiece con los valores predeterminados y ajústelos usando la prueba.",
                new("Umbral y frecuencia", "El umbral inicial es 0,90; la puntuación no es una probabilidad. Pruebe tanto el objetivo real como un fondo sin objetivo antes de ajustarlo. La detección se comprueba cada 200 ms por defecto, independientemente del intervalo global entre clics. Se necesitan dos coincidencias consecutivas."),
                new("Activación y espera", "Una vez por aparición pulsa solo una vez mientras la imagen siga presente. Dos comprobaciones consecutivas sin coincidencia permiten volver a activar. Una imagen ya visible al iniciar puede producir el primer clic. Repetir mientras visible sigue respetando la secuencia y el intervalo de clic. El límite inicial es 60 s; 0 espera sin límite. Al vencer se detiene toda la sesión. El descanso obligatorio entre clics no cuenta como espera de la condición.")),
            EuropeanPage(HelpTopic.ImageConditionTroubleshooting, "Resolver problemas visuales", "Pruebe el reconocimiento sin clics antes de reiniciar.",
                new("No reconoce o rechaza la imagen", "Solo se lee el escritorio visible. Mueva la aplicación y la guía fuera del área y restaure ventanas minimizadas. Use detalles estables y distintivos, no colores planos. En tamaño original la plantilla debe caber; active adaptación, recorte opcionalmente o amplíe el área. El modo automático no garantiza todas las escalas; rotación o temas distintos pueden requerir otra captura. Suba el umbral para evitar falsos positivos."),
                new("Falsos positivos, espera o lentitud", "Suba el umbral o elija una plantilla más distintiva si hay falsos positivos. Una imagen permanente no produce otro clic en Una vez por aparición; elija Repetir si necesita varios. La secuencia puede seguir esperando una entrada anterior. Un tiempo agotado detiene toda la sesión. Reduzca la zona de detección para bajar el coste. Las apariciones más breves que el intervalo de detección pueden pasar inadvertidas.")),
            EuropeanPage(HelpTopic.HotkeysAndConfiguration, "Atajos y configuraciones", "Guarde sus ajustes y conserve una forma rápida de detener los clics.",
                new("Iniciar y detener", "F6 es el atajo inicial y ESC detiene los clics activos. En Ajustes → Ajustes de teclas se admiten F6–F12, Insert, Home, End, PageUp, PageDown y Pause sin Ctrl, Alt, Shift ni Win. Los atajos se guardan por usuario de Windows, separados del JSON."),
                new("Guardar y cargar", "Detenga la sesión antes de editar o cargar. Archivo guarda zonas, botones, tiempos, secuencia y condiciones en JSON. Las plantillas quedan integradas, sin depender de una ruta externa. Las configuraciones antiguas sin condiciones mantienen los clics normales. SendInput genera entradas de software, no convierte los eventos en hardware real."),
                new("Guardado y restauración automáticos", "Al cerrar la ventana principal, la aplicación guarda la configuración actual para el usuario de Windows y la restaura en el próximo inicio. Archivo: %LOCALAPPDATA%\\MouseClicker\\last-session.json. Para empezar desde cero, cierre la aplicación y elimine ese archivo. Archivo → Guardar configuración sigue exportando un archivo JSON."))
        }));

        catalogs["ru-RU"] = new("Руководство", "Разделы", "Поиск по руководству…", "Разделы не найдены. Попробуйте другое слово.", "Закрыть", "Руководство по условным кликам", Array.AsReadOnly(new[]
        {
